enum OrderError { case LimitExceeded }

final case class Order(customerId: CustomerId, lines: List[Line], total: Money)

object Order:
  def open(customerId: CustomerId): Order = Order(customerId, Nil, Money.zero)

  // behaviour is a pure function over the data, not a method on it
  def addLine(o: Order, line: Line): Either[OrderError, Order] =
    if o.total + line.price > LIMIT then Left(OrderError.LimitExceeded)
    else Right(o.copy(lines = o.lines :+ line, total = o.total + line.price))
